#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> square(N, vector<int>(N));
    int missingRow = -1, missingCol = -1;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> square[i][j];
            if (square[i][j] == 0) {
                missingRow = i;
                missingCol = j;
            }
        }
    }

    int magicSum = 0;
    for (int i = 0; i < N; ++i) {
        if (i == missingRow) continue;
        for (int j = 0; j < N; ++j) {
            magicSum += square[i][j];
        }
        break;
    }

    int rowSum = 0;
    for (int j = 0; j < N; ++j) {
        rowSum += square[missingRow][j];
    }

    cout << magicSum - rowSum << '\n'
         << missingRow + 1 << '\n'
         << missingCol + 1 << '\n';

    return 0;
}
